package com.reevil.client.canon;

import com.reevil.entity.BioMonster;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.core.registries.BuiltInRegistries;

/** Generated by tools/canon_moves.py: shows mutation/form parts only while their condition holds; spins propellers. */
public final class CanonVisuals {
    private CanonVisuals() {}
    private static ModelPart part(ModelPart root, String path) {
        ModelPart p = root;
        for (String s : path.split("/")) { if (!p.hasChild(s)) return null; p = p.getChild(s); }
        return p;
    }
    public static void apply(ModelPart root, BioMonster e) {
        String id = BuiltInRegistries.ENTITY_TYPE.getKey(e.getType()).getPath();
        int mut = e.getMut(), form = e.getForm();
        float age = e.tickCount;
        switch (id) {
            case "adjule" -> {
                { ModelPart p = part(root, "body/chest/neck/head/splitL"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "body/chest/neck/head/splitR"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "body/chest/neck/head/plaga"); if (p != null) p.visible = mut == 1; }
            }
            case "dimitrescu" -> {
                { ModelPart p = part(root, "base/torso/wingL"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/wingR"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/neck/head/dhorn"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/dtail"); if (p != null) p.visible = mut == 1; }
            }
            case "fat_molded" -> {
                { ModelPart p = part(root, "body/waist/chest/neck/head"); if (p != null) p.visible = mut != 1; }
            }
            case "gnezdo" -> {
                { ModelPart p = part(root, "base/torso/queen"); if (p != null) p.visible = mut == 1; }
            }
            case "heisenberg" -> {
                { ModelPart p = part(root, "base/slug"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/slugGun"); if (p != null) p.visible = mut == 1; }
            }
            case "javo" -> {
                { ModelPart p = part(root, "base/torso/neck/head/mSluz"); if (p != null) p.visible = ((mut >> 8) & 15) == 1; }
                { ModelPart p = part(root, "base/torso/neck/head/mSmech"); if (p != null) p.visible = ((mut >> 8) & 15) == 2; }
                { ModelPart p = part(root, "base/torso/neck/head/mBeg"); if (p != null) p.visible = ((mut >> 8) & 15) == 3; }
                { ModelPart p = part(root, "base/torso/neck/head/mDim"); if (p != null) p.visible = ((mut >> 8) & 15) == 4; }
                { ModelPart p = part(root, "base/torso/armR/foreR/mSrp"); if (p != null) p.visible = ((mut >> 0) & 15) == 1; }
                { ModelPart p = part(root, "base/torso/armL/foreL/mKhv"); if (p != null) p.visible = ((mut >> 0) & 15) == 2; }
                { ModelPart p = part(root, "base/torso/armL/foreL/mBed"); if (p != null) p.visible = ((mut >> 0) & 15) == 3; }
                { ModelPart p = part(root, "base/mTrch"); if (p != null) p.visible = ((mut >> 4) & 15) == 1; }
                { ModelPart p = part(root, "base/mLetL"); if (p != null) p.visible = ((mut >> 4) & 15) == 2; }
                { ModelPart p = part(root, "base/mLetR"); if (p != null) p.visible = ((mut >> 4) & 15) == 2; }
                { ModelPart p = part(root, "base/mLetT"); if (p != null) p.visible = ((mut >> 4) & 15) == 2; }
                { ModelPart p = part(root, "base/mSkak"); if (p != null) p.visible = ((mut >> 4) & 15) == 3; }
                { ModelPart p = part(root, "base/mOkl"); if (p != null) p.visible = ((mut >> 4) & 15) == 4; }
                { ModelPart p = part(root, "base/torso/mEks"); if (p != null) p.visible = ((mut >> 12) & 15) == 1; }
                { ModelPart p = part(root, "base/torso/mKrl"); if (p != null) p.visible = ((mut >> 12) & 15) == 2; }
                { ModelPart p = part(root, "base/torso/mMag"); if (p != null) p.visible = ((mut >> 12) & 15) == 3; }
                { ModelPart p = part(root, "base/mChr"); if (p != null) p.visible = ((mut >> 12) & 15) == 4; }
            }
            case "marguerite" -> {
                { ModelPart p = part(root, "base/hive"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/armR/foreR/elong"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/lumps"); if (p != null) p.visible = mut == 1; }
            }
            case "mendez" -> {
                { ModelPart p = part(root, "base/torso/worm"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/bkL"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/bkR"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/spineX"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/armR/foreR/talonR"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/armL/foreL/talonL"); if (p != null) p.visible = mut == 1; }
            }
            case "moreau" -> {
                { ModelPart p = part(root, "body/head/maw"); if (p != null) p.visible = mut == 1; }
            }
            case "soldat" -> {
                { ModelPart p = part(root, "base/torso/armR/foreR/drillR"); if (p != null) p.visible = mut == 1 || mut == 3; }
                { ModelPart p = part(root, "base/torso/armL/foreL/drillL2"); if (p != null) p.visible = mut == 3; }
                { ModelPart p = part(root, "base/torso/armR/foreR/drillR2"); if (p != null) p.visible = mut == 3; }
                { ModelPart p = part(root, "base/torso/pz"); if (p != null) p.visible = mut == 3; }
                { ModelPart p = part(root, "base/torso/jet"); if (p != null) p.visible = mut == 2; }
            }
            case "sturm" -> {
                { ModelPart p = part(root, "base/torso/prop"); if (p != null) p.zRot = age * 0.9f; }
            }
            case "wesker" -> {
                { ModelPart p = part(root, "base/torso/uroT1"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT2"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT3"); if (p != null) p.visible = mut == 1; }
                { ModelPart p = part(root, "base/torso/uroT4"); if (p != null) p.visible = mut == 1; }
            }
            default -> {}
        }
    }
}
